if(!exists('build_credit_asset_pool'))library(creditratingsystem)
sp_D<-'2023-01-01'
sp_profile<-function(kind='ABS',cls='AUTO_LOAN',mode='STATIC')list(profile_id='p',version='1',known_at=sp_D,currency='EUR',product_kind=kind,pool_mode=mode,allowed_asset_classes=list(cls),maximum_dpd=30,exclude_disputed=TRUE,eligible_recourse=list('NONE','SELLER'),revolving_until=if(mode=='STATIC')NULL else'2024-01-01')
sp_asset<-function(id='a',cls='AUTO_LOAN')list(asset_id=id,asset_class=cls,invoice_id=if(cls=='INVOICE')paste0('invoice-',id)else NULL,obligor_id=paste0('o',id),default_group_id=paste0('g',id),seller_id='seller',servicer_id='service',currency='EUR',observed_at=sp_D,known_at=sp_D,origination_date='2022-01-01',balance_date=sp_D,principal_balance=100,schedule=list(list(date='2023-07-01',principal_due=40,interest_due=5),list(date='2024-01-01',principal_due=60,interest_due=3)),overdue_days=0,disputed=FALSE,dilution_reserve=0,recourse='NONE',collateral_allocations=list())
sp_assignment<-function(id='m',aid='a',pool='pool',share=1,start=sp_D,end=NULL)list(assignment_id=id,pool_id=pool,asset_id=aid,known_at=sp_D,effective_from=start,effective_until=end,share=share,purchase_price=share*100,purchase_priority=1)
sp_build<-function(assets=list(sp_asset()),assignments=list(sp_assignment()),p=sp_profile())build_credit_asset_pool(assets,assignments,p,'pool',sp_D,sp_D)$value
sp_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
