a<-sp_asset();a$known_at<-'2023-02-01';r<-sp_build(list(a));stopifnot(r$reference_principal==0,identical(r$excluded_assets[[1]]$reasons,list('NOT_YET_KNOWN_OR_OBSERVED')));a<-sp_asset();a$balance_date<-'2022-12-31';stopifnot(identical(sp_build(list(a))$excluded_assignments[[1]]$reasons,list('STALE_BALANCE')));p<-sp_profile();p$revolving_until<-'2024-01-01';sp_error('STRUCTURED_ROUTE',sp_build(p=p))
a<-sp_asset(cls='INVOICE');b<-sp_asset('b',cls='INVOICE');b$invoice_id<-a$invoice_id;sp_error('STRUCTURED_DUPLICATE',sp_build(list(a,b),p=sp_profile('TRADE_RECEIVABLES','INVOICE')));a<-sp_asset();b<-sp_asset('b');b$obligor_id<-a$obligor_id;sp_error('STRUCTURED_DEFAULT_GROUP',sp_build(list(a,b)));b$default_group_id<-a$default_group_id;a$collateral_allocations<-list(list(collateral_id='house',allocation_fraction=.6));b$collateral_allocations<-list(list(collateral_id='house',allocation_fraction=.5));sp_error('STRUCTURED_COLLATERAL',sp_build(list(a,b)));a<-sp_asset();a$schedule[[2]]$principal_due<-50;sp_error('STRUCTURED_SCHEDULE',sp_build(list(a)))
