sp_borrowing_profile<-function()list(profile_id='b',version='1',known_at=sp_D,currency='EUR',maximum_overdue_days=30,exclude_disputed=TRUE,allowed_recourse=list('NONE','SELLER'),advance_rates=list(NONE=.8,SELLER=.9),default_group_cap=.5,group_caps=setNames(list(),character()),additional_reserve=5,reserve_scope='ADDITIONAL_NOT_IN_INVOICE_DILUTION',coverage_status='COMPLETE')
